// `lumiose({ headers })` matching and the `_headers` file (TASK-125, decision-26 §4).
import { describe, expect, it } from "vitest";
import { DEFAULT_HEADERS, headersFile, headersFor, type HeaderRule } from "./headers.ts";

const D = DEFAULT_HEADERS;
const DEFAULTS_FILE =
  "# Generated by lumiose build: Lumiose's default headers and lumiose({ headers }).\n/*\n  x-content-type-options: nosniff\n  referrer-policy: strict-origin-when-cross-origin\n";

describe("headersFor()", () => {
  it("applies a record to every path", () => {
    const option = { "Cross-Origin-Opener-Policy": "same-origin" };
    expect(headersFor(option, "/")).toEqual({ ...D, "cross-origin-opener-policy": "same-origin" });
    expect(headersFor(option, "/songs/1")).toEqual({
      ...D,
      "cross-origin-opener-policy": "same-origin",
    });
  });

  it("matches * as one segment and ** as any depth; later rules win", () => {
    const option: HeaderRule[] = [
      { path: "/**", headers: { "x-a": "all" } },
      { path: "/blog/*", headers: { "x-b": "post" } },
      { path: "/assets/**", headers: { "x-a": "asset" } },
      { path: "/about", headers: { "x-c": "about" } },
    ];
    expect(headersFor(option, "/")).toEqual({ ...D, "x-a": "all" });
    expect(headersFor(option, "/blog/hello")).toEqual({ ...D, "x-a": "all", "x-b": "post" });
    expect(headersFor(option, "/blog")).toEqual({ ...D, "x-a": "all" });
    expect(headersFor(option, "/blog/a/b")).toEqual({ ...D, "x-a": "all" });
    expect(headersFor(option, "/assets/x/y.js")).toEqual({ ...D, "x-a": "asset" });
    expect(headersFor(option, "/about/")).toEqual({ ...D, "x-a": "all", "x-c": "about" });
  });
});

describe("headersFile()", () => {
  it("writes the static hosts' _headers format below base", () => {
    expect(headersFile({ "x-a": "1" }, "/")).toBe(`${DEFAULTS_FILE}/*\n  x-a: 1\n`);
    expect(
      headersFile([{ path: "/blog/*/**", headers: { "x-b": "2", "x-c": "3" } }], "/sub/"),
    ).toBe(`${DEFAULTS_FILE.replace("\n/*\n", "\n/sub/*\n")}/sub/blog/:p0/*\n  x-b: 2\n  x-c: 3\n`);
  });
});

describe("default headers (decision-29)", () => {
  it("sends nosniff and the referrer policy; lumiose({ headers }) overrides or removes them", () => {
    expect(headersFor(undefined, "/")).toEqual(D);
    expect(
      headersFor({ "Referrer-Policy": "no-referrer", "x-content-type-options": "" }, "/a"),
    ).toEqual({ "referrer-policy": "no-referrer" });
    expect(headersFile({ "x-content-type-options": "" }, "/")).toContain(
      "/*\n  ! x-content-type-options\n",
    );
  });
});
